import { useFormStatus } from "react-dom";

function SubmitButton() {
  const { pending } = useFormStatus();

  return (
    <button type="submit" disabled={pending}>
      {pending ? "Submitting..." : "Submit"}
    </button>
  );
}

export default function ContactForm({ sendMessage }) {
  return (
    <form action={sendMessage}>
      <input name="email" type="email" required />
      <SubmitButton />
    </form>
  );
}

import { useActionState } from "react";

async function subscribe(previousState, formData) {
  const email = formData.get("email");
  const res = await fetch("/api/subscribe", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email }),
  });

  if (!res.ok) {
    return { error: "Could not subscribe. Please try again.", done: false };
  }
  return { error: null, done: true };
}

export default function Newsletter() {
  const [state, formAction, isPending] = useActionState(subscribe, {
    error: null,
    done: false,
  });

  return (
    <form action={formAction}>
      <input name="email" type="email" required />
      <button type="submit" disabled={isPending}>
        {isPending ? "Subscribing..." : "Subscribe"}
      </button>
      {state.error && <p role="alert">{state.error}</p>}
      {state.done && <p>Thanks, you are subscribed.</p>}
    </form>
  );
}

import { useOptimistic, startTransition } from "react";

function LikeButton({ likes, saveLike }) {
  const [optimisticLikes, addOptimisticLike] = useOptimistic(
    likes,
    (currentLikes, amount) => currentLikes + amount
  );

  function handleClick() {
    startTransition(async () => {
      addOptimisticLike(1);
      // saveLike sends the request and updates `likes` in the parent.
      await saveLike();
    });
  }

  return <button onClick={handleClick}>Like ({optimisticLikes})</button>;
}

